AHB.audio({"groups": {"part-01-vocabulary": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-01-vocabulary/001.mp3", "text": "The team has a (1)… with NorthBridge."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-01-vocabulary/002.mp3", "text": "Mr. Tarek sends an (2)… first."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-01-vocabulary/003.mp3", "text": "He says, “(3)…, everyone.”"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-01-vocabulary/004.mp3", "text": "They talk about the next order."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-01-vocabulary/005.mp3", "text": "“Is June (4)…”"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-01-vocabulary/006.mp3", "text": "They (5)… on the plan and write the (6)"}], "title": "Read and listen"}], "part-02-grammar": [{"clips": [{"ar": "في الاجتماع، نوافق أو نرفض ببساطة وأدب.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-02-grammar/001.mp3", "text": "In a meeting, we agree or say no simply and politely."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-02-grammar/002.mp3", "text": "To SAY YES: Yes, that's possible."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-02-grammar/003.mp3", "text": "That's a good idea."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-02-grammar/004.mp3", "text": "To SAY NO POLITELY: Sorry, that's not possible."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-02-grammar/005.mp3", "text": "Let me check."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-02-grammar/006.mp3", "text": "We can discuss this."}, {"ar": "هذه عبارات قصيرة ولطيفة.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-02-grammar/007.mp3", "text": "These are short, kind phrases."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-02-grammar/008.mp3", "text": "At A2, we keep it simple — we do not need long, difficult words."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-02-grammar/009.mp3", "text": "We use CAN and COULD for polite requests in a meeting."}, {"ar": "can عادية. و could أكثر تهذيباً قليلاً.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-02-grammar/010.mp3", "text": "CAN is normal; COULD is a little more polite."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-02-grammar/011.mp3", "text": "Can we start now?"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-02-grammar/012.mp3", "text": "Could you send the agenda?"}, {"ar": "هل يمكنكم التسليم في حزيران؟", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-02-grammar/013.mp3", "text": "Can you deliver in June?"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-02-grammar/014.mp3", "text": "We answer: Yes, of course. / Sorry, not today."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-02-grammar/015.mp3", "text": "We use WOULD LIKE (I'd like / we'd like) to say what we want, politely."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-02-grammar/016.mp3", "text": "We would like to order more cement."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-02-grammar/017.mp3", "text": "We'd like a June delivery."}, {"ar": "هل تودّ أن نلتقي عبر الإنترنت؟", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-02-grammar/018.mp3", "text": "Would you like to meet online?"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-02-grammar/019.mp3", "text": "Remember: would like + to + verb, or would like + a noun."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-02-grammar/020.mp3", "text": "Keep it simple and polite."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-02-grammar/021.mp3", "text": "For agreement, short phrases are best: 'Yes, that's possible' or 'Sorry, not this time' (NOT long, difficult sentences)."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-02-grammar/022.mp3", "text": "Use 'would like', not 'want', to be polite: 'We would like to order more' (NOT 'We want to order more')."}], "title": "Read and listen"}], "part-03-listening": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-03-listening/001.mp3", "text": "Listen and read. (Your teacher will read the dialogue, or play the audio.)"}], "title": "Read and listen"}, {"clips": [{"ar": "أهلاً بك يا سيدة تشِن. شكراً على وقتك. هل نبدأ بجدول الأعمال؟", "speaker": "Mr. Tarek", "src": "../../assets/audio/unit-08/part-03-listening/002.mp3", "text": "Welcome, Ms. Chen. Thank you for your time. Shall we start with the agenda?"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-03-listening/003.mp3", "text": "Yes, of course. First, thank you for the last order. The cement was high quality."}, {"ar": "شكراً لك. ونحن سعداء أيضاً. ماذا تودّون هذه المرة؟", "speaker": "Mr. Tarek", "src": "../../assets/audio/unit-08/part-03-listening/004.mp3", "text": "Thank you. We are happy too. What would you like this time?"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-03-listening/005.mp3", "text": "We would like to order more — 2,000 tonnes. Can you deliver in June?"}, {"ar": "تسليم في حزيران. هل هذا ممكن يا فادي؟", "speaker": "Mr. Tarek", "src": "../../assets/audio/unit-08/part-03-listening/006.mp3", "text": "A June delivery — is that possible, Fadi?"}, {"ar": "نعم، هذا ممكن. يمكننا شحنه بحراً في أوائل حزيران.", "speaker": "Fadi", "src": "../../assets/audio/unit-08/part-03-listening/007.mp3", "text": "Yes, that's possible. We can ship it by sea in early June."}, {"ar": "جيد. ولطلب أكبر، هل يمكنكم منح خصم أكبر؟", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-03-listening/008.mp3", "text": "Good. And for a bigger order, could you give a bigger discount?"}, {"ar": "", "speaker": "Lina", "src": "../../assets/audio/unit-08/part-03-listening/009.mp3", "text": "For 2,000 tonnes, we can give 15% off. Is that good?"}, {"ar": "نعم، هذا جيد. نحن موافقون. شكراً للجميع.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-03-listening/010.mp3", "text": "Yes, that's good. We agree. Thank you, everyone."}], "title": "Dialogue D1"}, {"clips": [{"ar": "هل التسليم في حزيران ممكن؟", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-03-listening/011.mp3", "text": "Is a June delivery possible?"}, {"ar": "نعم، هذا ممكن. يمكننا الشحن في أوائل حزيران.", "speaker": "Fadi", "src": "../../assets/audio/unit-08/part-03-listening/012.mp3", "text": "Yes, that's possible. We can ship in early June."}, {"ar": "جيد. وهل يمكنكم إرسال البضائع بحراً؟", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-03-listening/013.mp3", "text": "Good. And could you send the goods by sea?"}, {"ar": "بالطبع. البحر أرخص للطلب الكبير.", "speaker": "Fadi", "src": "../../assets/audio/unit-08/part-03-listening/014.mp3", "text": "Of course. By sea is cheaper for a big order."}, {"ar": "ممتاز. وقائمة التعبئة، هل يمكنكم إرسالها مبكراً؟", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-03-listening/015.mp3", "text": "Perfect. And the packing list — can you send it early?"}, {"ar": "نعم، أستطيع. سأرسلها مع تحديث الشحن.", "speaker": "Fadi", "src": "../../assets/audio/unit-08/part-03-listening/016.mp3", "text": "Yes, I can. I will send it with the shipping update."}, {"ar": "شكراً لك. إذاً نحن متفقون.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-03-listening/017.mp3", "text": "Thank you. We agree, then."}], "title": "Dialogue D2"}], "part-04-speaking": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-04-speaking/001.mp3", "text": "A: Open the meeting ('Welcome."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-04-speaking/002.mp3", "text": "Shall we start?')."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-04-speaking/003.mp3", "text": "B: Say what you'd like ('We would like to order more')."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-04-speaking/004.mp3", "text": "A: Ask a question ('Can you…' / 'Is … possible?')."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-04-speaking/005.mp3", "text": "B: Agree or say no politely ('Yes, that's possible')."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-04-speaking/006.mp3", "text": "A: Close and agree the next steps ('Let's agree on…')."}], "title": "Read and listen"}], "part-05-reading": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-05-reading/001.mp3", "text": "What makes a good meeting?"}, {"ar": "يظن كثيرون أن الاجتماع يجب أن يكون طويلاً، بكلمات كبيرة وأفكار صعبة.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-05-reading/002.mp3", "text": "Many people think a meeting must be long, with big words and hard ideas."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-05-reading/003.mp3", "text": "But this is wrong."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-05-reading/004.mp3", "text": "The best meetings are short, simple, and clear."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-05-reading/005.mp3", "text": "A good meeting does three things: it starts well, it stays clear, and it ends with an agreement."}, {"ar": "أولاً، الاجتماع الجيد يبدأ جيداً.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-05-reading/006.mp3", "text": "First, a good meeting starts well."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-05-reading/007.mp3", "text": "Before the meeting, the leader sends an agenda — a short list of the things to talk about."}, {"ar": "الآن يعرف الجميع الخطة.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-05-reading/008.mp3", "text": "Now everyone knows the plan."}, {"ar": "عندما يبدأ الاجتماع، يرحّب القائد بالجميع ويقول: هل نبدأ؟", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-05-reading/009.mp3", "text": "When the meeting begins, the leader welcomes everyone and says, 'Shall we start?'"}, {"ar": "ترحيب دافئ وجدول أعمال واضح. هذه بداية جيدة.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-05-reading/010.mp3", "text": "A warm welcome and a clear agenda: this is a good start."}, {"ar": "ثانياً، الاجتماع الجيد يبقى واضحاً.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-05-reading/011.mp3", "text": "Second, a good meeting stays clear."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-05-reading/012.mp3", "text": "People use simple words."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-05-reading/013.mp3", "text": "They speak one at a time."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-05-reading/014.mp3", "text": "They listen to each other."}, {"ar": "عندما يريد أحدهم شيئاً، يقوله ببساطة: نودّ أن نطلب المزيد.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-05-reading/015.mp3", "text": "When someone wants something, they say it simply: 'We would like to order more.'"}, {"ar": "وعندما يوافق أحدهم، يقولها ببساطة: نعم، هذا ممكن.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-05-reading/016.mp3", "text": "When someone agrees, they say it simply: 'Yes, that's possible.'"}, {"ar": "لا خطب طويلة ولا كلمات صعبة.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-05-reading/017.mp3", "text": "There are no long speeches and no difficult words."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-05-reading/018.mp3", "text": "Everyone understands everyone."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-05-reading/019.mp3", "text": "This is the secret: clear is better than clever."}, {"ar": "ثالثاً، الاجتماع الجيد ينتهي باتفاق.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-05-reading/020.mp3", "text": "Third, a good meeting ends with an agreement."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-05-reading/021.mp3", "text": "This is the most important part."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-05-reading/022.mp3", "text": "A meeting with no agreement is a waste of time."}, {"ar": "لذلك في النهاية، يقول القائد: لنتفق على الخطوات التالية.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-05-reading/023.mp3", "text": "So, at the end, the leader says: 'Let's agree the next steps.'"}, {"ar": "عندئذٍ يعرف الجميع ما يجب فعله بعد ذلك.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-05-reading/024.mp3", "text": "Then everyone knows what to do next."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-05-reading/025.mp3", "text": "'We send a quotation."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-05-reading/026.mp3", "text": "You send the order."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-05-reading/027.mp3", "text": "We ship in June.'"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-05-reading/028.mp3", "text": "Now the meeting has a result."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-05-reading/029.mp3", "text": "Everyone leaves with a clear plan."}, {"ar": "وهذا هو هدف الاجتماع: ليس الكلام، بل الاتفاق والعمل.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-05-reading/030.mp3", "text": "And that is the point of a meeting: not to talk, but to agree and to act."}, {"ar": "لذا تذكّر: اجعله قصيراً، واجعله واضحاً، وأنهِه دائماً باتفاق.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-05-reading/031.mp3", "text": "So remember: keep it short, keep it clear, and always end with an agreement."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-05-reading/032.mp3", "text": "Do this, and your meetings will be good — and short."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-05-reading/033.mp3", "text": "And everyone will thank you for it."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-05-reading/034.mp3", "text": "The best meetings are short, simple, and (1)"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-05-reading/035.mp3", "text": "They start with a warm welcome and an (2)"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-05-reading/036.mp3", "text": "People use (3)… words and listen to each other."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-05-reading/037.mp3", "text": "And they end with an (4)…, so everyone knows the next (5)"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-05-reading/038.mp3", "text": "The point of a meeting is to agree and to (6)"}], "title": "Read and listen"}], "part-06-writing": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-06-writing/001.mp3", "text": "Sentence starters: “We would like to meet you.” · “Can we meet on …” · “On the agenda: …”"}], "title": "Read and listen"}], "part-07-trade-skills": [{"clips": [{"ar": "الاجتماع الجيد يبدأ قبل الاجتماع، بجدول الأعمال.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-07-trade-skills/001.mp3", "text": "A good meeting starts before the meeting — with the agenda."}, {"ar": "جدول الأعمال قائمة قصيرة بما سيُناقش، بالترتيب.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-07-trade-skills/002.mp3", "text": "An agenda is a short list of the things to talk about, in order."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-07-trade-skills/003.mp3", "text": "Why is it so useful?"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-07-trade-skills/004.mp3", "text": "First, it helps everyone prepare."}, {"ar": "عندما يعرف الناس الخطة، يأتون مستعدين.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-07-trade-skills/005.mp3", "text": "When people know the plan, they come ready."}, {"ar": "ثانياً، يُبقي الاجتماع في مساره.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-07-trade-skills/006.mp3", "text": "Second, it keeps the meeting on track."}, {"ar": "عندما يخرج الاجتماع عن الخطة، يقول القائد: لنعد إلى جدول الأعمال.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-07-trade-skills/007.mp3", "text": "When the meeting goes off the plan, the leader says, 'Let's go back to the agenda.'"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-07-trade-skills/008.mp3", "text": "Third, it saves time."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-07-trade-skills/009.mp3", "text": "With an agenda, a meeting is short and clear."}, {"ar": "بدونه، قد يستمر الاجتماع بلا نهاية، وبلا نتيجة.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-07-trade-skills/010.mp3", "text": "Without one, a meeting can go on and on, with no result."}, {"ar": "جدول الأعمال الجيد بسيط: تاريخ ووقت، ثم ثلاث أو أربع نقاط، ثم الخطوات التالية.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-07-trade-skills/011.mp3", "text": "A good agenda is simple: a date and time, then three or four points, then 'next steps'."}, {"ar": "وفي الاجتماع نفسه، للناس أدوار.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-07-trade-skills/012.mp3", "text": "In the meeting itself, people have roles."}, {"ar": "القائد يفتتح الاجتماع، ويتبع جدول الأعمال، ويختتمه.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-07-trade-skills/013.mp3", "text": "The LEADER opens the meeting, follows the agenda, and closes it."}, {"ar": "الجميع يقدّم أفكاراً ويستمع.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-07-trade-skills/014.mp3", "text": "EVERYONE gives ideas and listens."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-07-trade-skills/015.mp3", "text": "And one person — the NOTE-TAKER — writes the notes: what the meeting agreed, and the next steps."}, {"ar": "بعد الاجتماع، يرسل مدوّن الملاحظات الملاحظات إلى الجميع.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-07-trade-skills/016.mp3", "text": "After the meeting, the note-taker sends the notes to everyone."}, {"ar": "الآن يوجد سجلّ مكتوب للاتفاق.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-07-trade-skills/017.mp3", "text": "Now there is a written record of the agreement."}, {"ar": "جدول أعمال واضح، وأدوار واضحة، وملاحظات واضحة. هذه الأمور الثلاثة مهمة.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-07-trade-skills/018.mp3", "text": "A clear agenda, clear roles, and clear notes: these three things matter."}, {"ar": "إنها تحوّل الاجتماع من حديث طويل إلى عمل جماعي جيد وسريع.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-07-trade-skills/019.mp3", "text": "They turn a meeting from a long talk into good, fast teamwork."}], "title": "Read and listen"}], "part-08-consolidation": [{"clips": [{"ar": "كان الاجتماع قصيراً وجيداً.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-08-consolidation/001.mp3", "text": "The meeting was short and good."}, {"ar": "الآن حان وقت أهم جزء: الاتفاق.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-08-consolidation/002.mp3", "text": "Now it is time for the most important part: the agreement."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-08-consolidation/003.mp3", "text": "Mr. Tarek looks at his notes."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-08-consolidation/004.mp3", "text": "“Let's agree the next steps,” he says."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-08-consolidation/005.mp3", "text": "“First, we send a quotation for 2,000 tonnes, with a 15% discount."}, {"ar": "ثم ترسلون الطلب.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-08-consolidation/006.mp3", "text": "Then you send the order."}, {"ar": "ثم نشحن الإسمنت في أوائل حزيران، بحراً.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-08-consolidation/007.mp3", "text": "Then we ship the cement in early June, by sea."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-08-consolidation/008.mp3", "text": "And then you pay on time."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-08-consolidation/009.mp3", "text": "Is that right?”"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-08-consolidation/010.mp3", "text": "“Yes, that's right,” says Ms. Chen."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-08-consolidation/011.mp3", "text": "Everyone is clear."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-08-consolidation/012.mp3", "text": "Everyone knows the plan."}, {"ar": "لا كلمات كبيرة، ولا أفكار صعبة.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-08-consolidation/013.mp3", "text": "There are no big words, and no hard ideas."}, {"ar": "مجرد أربع خطوات بسيطة، ونعم من الطرفين.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-08-consolidation/014.mp3", "text": "Just four simple steps, and a 'yes' from both sides."}, {"ar": "هذا اتفاق جيد: قصير وواضح وعادل للطرفين.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-08-consolidation/015.mp3", "text": "This is a good agreement: short, clear, and fair for both."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-08-consolidation/016.mp3", "text": "After the meeting, Fadi sends the notes to everyone: “Thank you for the good meeting."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-08-consolidation/017.mp3", "text": "We agreed the next steps: 1) We send a quotation. 2) You send the order. 3) We ship in June. 4) You pay on time.”"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-08-consolidation/018.mp3", "text": "Now there is a written record."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-08-consolidation/019.mp3", "text": "If anyone forgets, they can read the notes."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-08-consolidation/020.mp3", "text": "Karim reads them and smiles."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-08-consolidation/021.mp3", "text": "“A good meeting,” he thinks."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-08-consolidation/022.mp3", "text": "“We talked, we agreed, and now we all know the plan."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-08-consolidation/023.mp3", "text": "That is teamwork."}, {"ar": "والاتفاق الواضح اليوم يوفّر مئة رسالة غداً.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-08-consolidation/024.mp3", "text": "And a clear agreement today saves a hundred emails tomorrow.”"}], "title": "Read and listen"}], "part-09-cases": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-09-cases/001.mp3", "text": "A partner starts a meeting with no agenda."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-09-cases/002.mp3", "text": "Nobody knows the plan."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-09-cases/003.mp3", "text": "People talk about many things, but they agree on nothing."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-09-cases/004.mp3", "text": "After an hour, the meeting ends with no result."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-09-cases/005.mp3", "text": "Write one sentence to open a meeting with an agenda."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-09-cases/006.mp3", "text": "A partner asks for a very big discount — 40% off."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-09-cases/007.mp3", "text": "You cannot give that much."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-09-cases/008.mp3", "text": "But you do not want to be rude, and you want to keep the partner."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-09-cases/009.mp3", "text": "A meeting ends with a good agreement."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-09-cases/010.mp3", "text": "But nobody writes the notes."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-09-cases/011.mp3", "text": "One week later, the two sides do not agree on what they agreed."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-09-cases/012.mp3", "text": "There is confusion."}], "title": "Read and listen"}], "part-10-review": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-10-review/001.mp3", "text": "The meeting is online, at 10 o'clock."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-10-review/002.mp3", "text": "Mr. Tarek welcomes everyone and follows the agenda."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-10-review/003.mp3", "text": "Ms. Chen would like to order 2,000 tonnes."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-10-review/004.mp3", "text": "A June delivery is possible, and Lina gives a 15% discount."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-10-review/005.mp3", "text": "They agree the next steps and close the meeting."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-10-review/006.mp3", "text": "[Teacher reads] 'Welcome, everyone."}, {"ar": "هل نبدأ بجدول الأعمال؟", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-10-review/007.mp3", "text": "Shall we start with the agenda?"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-10-review/008.mp3", "text": "We would like to order 2,000 tonnes."}, {"ar": "هل التسليم في حزيران ممكن؟", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-10-review/009.mp3", "text": "Is a June delivery possible?"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-10-review/010.mp3", "text": "Yes, that's possible, with a 15% discount."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-10-review/011.mp3", "text": "Good, we agree.'"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-10-review/012.mp3", "text": "I can follow an agenda and give simple ideas."}], "title": "Read and listen"}], "part-11-foundations": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-11-foundations/001.mp3", "text": "This unit is about meetings."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-11-foundations/002.mp3", "text": "But it points to a deep and important skill: the art of agreement."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-11-foundations/003.mp3", "text": "This is how two sides find a 'yes' that is good for both."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-11-foundations/004.mp3", "text": "This skill is useful everywhere: at work, at home, between friends, and even between countries."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-11-foundations/005.mp3", "text": "The person who can help two sides agree is one of the most valuable people in any group."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-11-foundations/006.mp3", "text": "How do you help two sides agree?"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-11-foundations/007.mp3", "text": "The first step is not to speak."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-11-foundations/008.mp3", "text": "It is to listen."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-11-foundations/009.mp3", "text": "Many people think agreement is about talking — about winning with clever words."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-11-foundations/010.mp3", "text": "But this is wrong."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-11-foundations/011.mp3", "text": "The best way to agree is to listen first."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-11-foundations/012.mp3", "text": "When you listen, you understand what the other side really wants."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-11-foundations/013.mp3", "text": "And when people feel heard, they relax, and they want to agree too."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-11-foundations/014.mp3", "text": "So the art of agreement starts with a quiet ear, not a loud voice."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-11-foundations/015.mp3", "text": "The second step is to look for the 'yes' that is good for both."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-11-foundations/016.mp3", "text": "A bad agreement is one where one side wins and one side loses."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-11-foundations/017.mp3", "text": "The losing side is unhappy, and next time, they do not come back."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-11-foundations/018.mp3", "text": "A good agreement is different: both sides get something they want."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-11-foundations/019.mp3", "text": "In this unit, Al-Hasan gets a bigger order, and NorthBridge gets a bigger discount."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-11-foundations/020.mp3", "text": "Both are happy."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-11-foundations/021.mp3", "text": "Both come back."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-11-foundations/022.mp3", "text": "This is the secret: do not try to win."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-11-foundations/023.mp3", "text": "Try to find the deal where everyone wins."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-11-foundations/024.mp3", "text": "Then everyone wants to work with you again."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-11-foundations/025.mp3", "text": "So as you work with partners, remember the art of agreement."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-11-foundations/026.mp3", "text": "Listen more than you speak."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-11-foundations/027.mp3", "text": "Look for the 'yes' that is good for both sides."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-11-foundations/028.mp3", "text": "And keep it simple and kind."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-11-foundations/029.mp3", "text": "You do not need clever words or hard tricks."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-11-foundations/030.mp3", "text": "You need an open ear, a fair heart, and a clear plan."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-11-foundations/031.mp3", "text": "Do this, and people will love to work with you."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-11-foundations/032.mp3", "text": "They will trust you, and they will come back, again and again."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-11-foundations/033.mp3", "text": "Because in business and in life, the greatest skill is not winning against people."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-11-foundations/034.mp3", "text": "It is finding the way forward together."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-11-foundations/035.mp3", "text": "Think of a time you and another person did not agree."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-11-foundations/036.mp3", "text": "How did you find a 'yes'?"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-11-foundations/037.mp3", "text": "Did you listen?"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-11-foundations/038.mp3", "text": "Did both sides get something?"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-11-foundations/039.mp3", "text": "Tell your partner."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-11-foundations/040.mp3", "text": "Write a few sentences (30–50 words) about a meeting."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/part-11-foundations/041.mp3", "text": "Use 'would like', a request ('Can you…'), and a simple agreement ('Yes, that's possible')."}], "title": "Read and listen"}], "warm-up": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/warm-up/001.mp3", "text": "Look at the pictures."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/warm-up/002.mp3", "text": "Answer these questions before you read."}, {"ar": "اكتملت الصفقة الأولى مع نورث بريدج.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/warm-up/003.mp3", "text": "The first deal with NorthBridge is complete."}, {"ar": "وصل الإسمنت، ودفعت السيدة تشِن في موعدها.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/warm-up/004.mp3", "text": "The cement arrived, and Ms. Chen paid on time."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/warm-up/005.mp3", "text": "Now both companies want to do more business."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/warm-up/006.mp3", "text": "So they have a meeting."}, {"ar": "في الاجتماع، يتحدث الناس معاً ويتفقون على خطة.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/warm-up/007.mp3", "text": "In a meeting, people talk together and agree on a plan."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/warm-up/008.mp3", "text": "The meeting is online."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/warm-up/009.mp3", "text": "Mr. Tarek, the General Manager, leads it."}, {"ar": "أولاً، يرسل جدول أعمال، وهو قائمة بالأمور التي ستُناقش.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/warm-up/010.mp3", "text": "First, he sends an agenda — a list of things to talk about."}, {"ar": "جدول الأعمال قصير: ترحيب، والطلب السابق، والطلب القادم، والأسعار، والخطوات التالية.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/warm-up/011.mp3", "text": "The agenda is short: welcome, the last order, the next order, prices, and next steps."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/warm-up/012.mp3", "text": "At 10 o'clock, the meeting begins."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/warm-up/013.mp3", "text": "“Welcome, Ms. Chen,” says Mr. Tarek."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/warm-up/014.mp3", "text": "“Thank you for your time."}, {"ar": "هل نبدأ بجدول الأعمال؟", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/warm-up/015.mp3", "text": "Shall we start with the agenda?”"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/warm-up/016.mp3", "text": "“Yes, of course,” says Ms. Chen."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/warm-up/017.mp3", "text": "“We are happy with the last order."}, {"ar": "كان الإسمنت عالي الجودة.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/warm-up/018.mp3", "text": "The cement was high quality."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/warm-up/019.mp3", "text": "We would like to order more.”"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/warm-up/020.mp3", "text": "“That is good news,” says Mr. Tarek."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/warm-up/021.mp3", "text": "“How much would you like this time?”"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/warm-up/022.mp3", "text": "“We'd like 2,000 tonnes,” says Ms. Chen."}, {"ar": "هل يمكنكم التسليم في حزيران؟", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/warm-up/023.mp3", "text": "“Can you deliver in June?”"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/warm-up/024.mp3", "text": "Mr. Tarek looks at Fadi."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/warm-up/025.mp3", "text": "“A June delivery — is that possible?”"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/warm-up/026.mp3", "text": "“Yes, that's possible,” says Fadi."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/warm-up/027.mp3", "text": "“We can ship it by sea in early June.”"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/warm-up/028.mp3", "text": "“And the price?” asks Ms. Chen."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/warm-up/029.mp3", "text": "“For a bigger order, can you give a bigger discount?”"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/warm-up/030.mp3", "text": "Lina answers."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/warm-up/031.mp3", "text": "“For 2,000 tonnes, we can give 15% off."}, {"ar": "هل هذا مناسب لكم؟", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/warm-up/032.mp3", "text": "Is that good for you?”"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/warm-up/033.mp3", "text": "“Yes, that's good,” says Ms. Chen."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/warm-up/034.mp3", "text": "The meeting ends well."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/warm-up/035.mp3", "text": "They agree the next steps: Al-Hasan sends a quotation, NorthBridge sends the order, and Al-Hasan ships in June."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/warm-up/036.mp3", "text": "“Thank you, everyone,” says Mr. Tarek."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/warm-up/037.mp3", "text": "“This was a good meeting."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/warm-up/038.mp3", "text": "We agree on the plan."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/warm-up/039.mp3", "text": "Let's do good business again.”"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/warm-up/040.mp3", "text": "Everyone is happy."}, {"ar": "اجتماع قصير وواضح وودّي، وطلب جديد في الطريق.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-08/warm-up/041.mp3", "text": "A short, clear, friendly meeting — and a new order on the way."}], "title": "Read and listen"}]}, "unit": 8});
